"""Read-only frozen-control runner; safe for the Cursor review sandbox."""
import copy,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT))
from src.common_catalogue import retrieve,validate_positive
from src.catalogue_gerber import extract_opening,extract_copper
from src.ingestion_files import verify

base=Path(__file__).parent/'controls'
inventory=json.loads((base/'inventory.json').read_text());verify(base,[{'path':p,'sha256':h} for p,h in inventory.items()])
out=[];positive=None
for control in json.loads((base/'controls.json').read_text()):
    try:
        r=retrieve(ROOT/control['bundle'],control['revision']);validate_positive(r);status='PASS';reason=None
        if control['name']=='positive':positive=(control,r)
    except Exception as error:status='REJECT';reason=str(error)
    assert status==control['expected'],(control,status,reason)
    out.append({'control':control['name'],'observed':status,'reason':reason})
for name,fn in [('ambiguous_mask',lambda:extract_opening((base/'ambiguous_mask.gbr').read_bytes(),[10.47,10])),
                ('duplicate_copper',lambda:extract_copper((base/'duplicate_copper.gbr').read_bytes()))]:
    try:fn()
    except ValueError as error:out.append({'control':name,'observed':'REJECT','reason':str(error)})
    else:raise AssertionError('False pass: '+name)
control,original=positive
truncated=copy.deepcopy(original);truncated['roles'].pop()
try:validate_positive(truncated)
except ValueError as error:out.append({'control':'truncated_result','observed':'REJECT','reason':str(error)})
else:raise AssertionError('Truncated result passed')
original['roles'][0]['native']['net_name']='CALLER MUTATION'
assert retrieve(ROOT/control['bundle'],control['revision'])['result_sha256']==original['result_sha256']
out.append({'control':'caller_mutation','observed':'ISOLATED'})
print(json.dumps({'status':'PASS','controls':out}))
